function validate([nums]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1e9 || v > 1e9)) return 'Each value is an integer between -10^9 and 10^9.';
  return null;
}

