function minimumPairRemoval(nums) {
  const n = nums.length;
  const values = [...nums];
  const prev = Array.from({ length: n }, (_, i) => i - 1);
  const next = Array.from({ length: n }, (_, i) => (i + 1 < n ? i + 1 : -1));
  const pairs = [];
  const lowerBound = (sum, left) => {
    let low = 0;
    let high = pairs.length;
    while (low < high) {
      const mid = (low + high) >> 1;
      const [midSum, midLeft] = pairs[mid];
      if (midSum < sum || (midSum === sum && midLeft < left)) {
        low = mid + 1;
      } else {
        high = mid;
      }
    }
    return low;
  };
  const hasPair = (left) => left !== -1 && next[left] !== -1;
  const insertPair = (left) => {
    if (!hasPair(left)) return;
    const sum = values[left] + values[next[left]];
    pairs.splice(lowerBound(sum, left), 0, [sum, left]);
  };
  const erasePair = (left) => {
    if (!hasPair(left)) return;
    pairs.splice(lowerBound(values[left] + values[next[left]], left), 1);
  };
  const outOfOrder = (left) => (hasPair(left) && values[left] > values[next[left]] ? 1 : 0);
  let badPairs = 0;
  for (let i = 0; i + 1 < n; i++) {
    insertPair(i);
    badPairs += outOfOrder(i);
  }
  let operations = 0;
  while (badPairs > 0) {
    const [sum, left] = pairs[0];
    const right = next[left];
    const before = prev[left];
    badPairs -= outOfOrder(before) + outOfOrder(left) + outOfOrder(right);
    erasePair(before);
    erasePair(left);
    erasePair(right);
    values[left] = sum;
    next[left] = next[right];
    if (next[right] !== -1) {
      prev[next[right]] = left;
    }
    badPairs += outOfOrder(before) + outOfOrder(left);
    insertPair(before);
    insertPair(left);
    operations++;
  }
  return operations;
}

