function minimumPairRemoval(nums) {
  // Replay the operations on a plain array, rescanning it every time.
  const arr = nums.slice();
  let count = 0;
  const isSorted = () => arr.every((value, i) => i === 0 || arr[i - 1] <= value);
  while (!isSorted()) {
    let at = 0;
    for (let i = 1; i + 1 < arr.length; i++) {
      if (arr[i] + arr[i + 1] < arr[at] + arr[at + 1]) at = i;
    }
    arr.splice(at, 2, arr[at] + arr[at + 1]);
    count++;
  }
  return count;
}

