function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size !== 'large') {
    const span = pick(1, 6);
    return [Array.from({ length: pick(1, 8) }, () => pick(-span, span))];
  }
  const n = 2000;
  const mode = pick(0, 3);
  if (mode === 0) return [Array.from({ length: n }, () => pick(-1e9, 1e9))];
  if (mode === 1) {
    // Non-increasing values force many merges.
    const nums = [];
    let value = 1e9;
    for (let i = 0; i < n; i++) {
      nums.push(value);
      value -= pick(0, 1e6);
    }
    return [nums];
  }
  if (mode === 2) {
    // Sorted values with a few neighbours swapped.
    const nums = Array.from({ length: n }, () => pick(-1e9, 1e9)).sort((a, b) => a - b);
    for (let k = pick(1, 6); k > 0; k--) {
      const i = pick(0, n - 2);
      [nums[i], nums[i + 1]] = [nums[i + 1], nums[i]];
    }
    return [nums];
  }
  // Tiny values make many equal sums, so the leftmost rule matters.
  return [Array.from({ length: n }, () => pick(-3, 3))];
}
